import React, { useCallback, useState } from 'react';
import { AppEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { Action } from '@thoughtspot/visual-embed-sdk';
import { useTier } from '../config/TierContext';

export default function Portfolios() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot AppEmbed]', err);
  }, []);

  return (
    <div style={{ minHeight: '100%', backgroundColor: '#F9FAFB', display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: '2rem 2.5rem 1rem', flexShrink: 0 }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#2c313c', margin: 0 }}>Portfolios</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0' }}>
          Your saved liveboards and collections on ThoughtSpot.
        </p>
      </div>

      <div style={{ padding: '0 2.5rem 2rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            border: '1px solid #E5E7EB',
            overflow: 'hidden',
            flex: 1,
            minHeight: 'calc(100vh - 180px)',
          }}
        >
          <AppEmbed
            path="insights/home/liveboards"
            showPrimaryNavbar={false}
            hiddenActions={[
              ...hiddenActions,
              Action.EditACopy,
              Action.MakeACopy,
            ]}
            disabledActions={disabledActions}
            onError={onError}
            additionalFlags={{
              myLibraryDefaultTab: 'MY_LIVEBOARDS',
            }}
            style={{ width: '100%', height: 'calc(100vh - 180px)' }}
          />
        </div>
      </div>
    </div>
  );
}
